<?php declare(strict_types=1); header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');header('Pragma: no-cache');header('Expires: 0');header('Surrogate-Control: no-store');header('CDN-Cache-Control: no-store');function out($x,$s=200){http_response_code($s);echo json_encode($x,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE);exit;}try{$world=(string)($_GET['world']??'GW001');if(!preg_match('/^GW00[1-9]$|^GW010$/D',$world))out(['ok'=>false,'error'=>'invalid_world'],422);$resource=(string)($_GET['resource']??'context');$base=dirname(__DIR__).'/nexus/public/';require_once $base.'core.php';require_once $base.'hub.php';$config=require dirname(__DIR__).'/__imc_private_gateway/config.php';$cfg=$config['db'];$family=in_array($world,['GW002','GW003','GW007','GW008'],true)?'gold':'custom';$pdo=new PDO(sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',$cfg['host'],$cfg['port'],$cfg[$family]),$cfg['user'],$cfg['pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$core=nexus_core_db($cfg);if($resource==='context'){out(['ok'=>true,'world'=>$world,'seasons'=>nexus_core_rows($core,'SELECT imc_season,imc_season_start_date,imc_season_end_date FROM `IMC Game World Season` WHERE game_world_id=? ORDER BY imc_season DESC',[$world])]);}if($resource==='catalog')out(['ok'=>true,'rows'=>nexus_catalog($pdo,$core,$world,nexus_season($core,$world,(string)($_GET['season']??'')))]);if($resource==='competition')out(nexus_hub($pdo,$core,$world));if($resource==='managers'){out(['ok'=>true,'world'=>$world,'rows'=>nexus_core_rows($core,'SELECT a.manager_id,m.full_name,m.sm_manager_id,a.team_id,a.national_team_id,a.team_name,a.assignment_type,a.start_date,a.end_date FROM `IMC Manager Assignment Global` a LEFT JOIN `IMC Manager Codex Global` m ON m.manager_id=a.manager_id WHERE a.game_world_id=? ORDER BY m.full_name,a.start_date DESC',[$world])]);}if($resource==='teams'){$clubs=nexus_core_rows($core,'SELECT m.*,c.* FROM `IMC Game World Club Mapping` m LEFT JOIN `IMC Club Codex Global` c ON c.id=m.`Club ID` WHERE m.`Game World`=? ORDER BY m.`Club Name`',[$world]);$nations=nexus_core_rows($core,'SELECT m.*,n.* FROM `IMC Game World National Team Mapping` m LEFT JOIN `IMC National Team Codex Global` n ON n.id=m.`National Team ID` WHERE m.`Game World`=? ORDER BY m.`National Team Name`',[$world]);out(['ok'=>true,'world'=>$world,'clubs'=>$clubs,'nations'=>$nations]);}$allowed=['results','schedule','transfers','players'];if(!in_array($resource,$allowed,true))out(['ok'=>false,'error'=>'invalid_resource'],422);$_GET['world']=$world;$_GET['resource']=$resource;ob_start();include $base.'data.php';}catch(Throwable $e){out(['ok'=>false,'error'=>'data_unavailable'],500);}